INSERT INTO magnet_v2_download_task (
    task_uuid, user_id, resource_id, status, selected_bytes, verified_bytes, priority,
    speed_limit, revision, retry_count, next_retry_at, error_code, error_message,
    created_at, updated_at
) VALUES (
    #{taskUuid}, #{userId}, #{resourceId}, #{status}, #{selectedBytes}, #{verifiedBytes}, #{priority},
    #{speedLimit}, #{revision}, #{retryCount}, #{nextRetryAt}, #{errorCode}, #{errorMessage},
    #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE magnet_v2_download_task
SET status = #{status},
    revision = #{newRevision},
    error_code = #{errorCode},
    error_message = #{errorMessage},
    updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{id}
  AND user_id = #{userId}
  AND revision = #{expectedRevision}
  AND deleted = 0

UPDATE magnet_v2_download_task
SET deleted = id, updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted = 0

mapper.select:
SELECT id, task_uuid, user_id, resource_id, status, selected_bytes, verified_bytes, priority, speed_limit, revision, retry_count, next_retry_at, error_code, error_message, created_at, updated_at, deleted FROM magnet_v2_download_task WHERE deleted = 0 AND status IN
#{status}
AND (next_retry_at IS NULL OR next_retry_at <= #{now}) ORDER BY CASE WHEN next_retry_at IS NULL THEN 0 ELSE 1 END, next_retry_at, id LIMIT #{limit}
